def sliced(iterable, maxsplit=1):
    return list(iterable)

def split_after(iterable, separator):
    return list(iterable)

def split_at(iterable, separator, keep_separator=False):
    return list(iterable)

def split_before(iterable, separator):
    return list(iterable)

def split_when(iterable, predicate, maxsplit=1):
    return list(iterable)
def zip_equal(*iterables):
    if len(set(map(len, iterables))) > 1:
        raise UnequalIterablesError
    return list(zip(*iterables))
def stagger(*iterables):
    try:
        return list(zip(*iterables))
    except ValueError:
        pass
    return list(zip(*iterables))
